def compute(vars):
    current_2006 = vars["v1"]
    total_commitments = vars["v2"]
    if total_commitments == 0:
        return None

    ratio = current_2006 / total_commitments
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "current_2006": current_2006,
            "total_commitments": total_commitments,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "percentage",
                "unit": "percentage"
            }
        }
    }
